css:
.btn {--sh-plate:0 .5px 1px 1px rgb(0 0 0/.3);--sh-card:0 0 0 1px rgb(0 0 0/.3);--sh-overlay:0 3px 8px rgb(0 0 0/.13),0 2px 5px rgb(0 0 0/.13),0 1px 1px rgb(0 0 0/.13);position:relative;display:inline-flex;align-items:center;justify-content:center;width:fit-content;flex-shrink:0;white-space:nowrap;border-radius:var(--radius-md);text-box-trim:trim-both;border:var(--spacing-hairline) solid transparent;font-family:var(--font-sans);font-weight:var(--font-weight-medium);letter-spacing:var(--tracking-snug);transition:color 100ms cubic-bezier(.4,0,.2,1),background-color 100ms cubic-bezier(.4,0,.2,1),border-color 100ms cubic-bezier(.4,0,.2,1);outline:none;user-select:none;cursor:pointer;-webkit-font-smoothing:antialiased;box-sizing:border-box}
:where([data-doop-theme="light"]) .btn {--sh-plate:0 1px 2px rgb(0 0 0/.05);--sh-card:0 0 0 .5px rgb(0 0 0/.11);--sh-overlay:0 6px 18px rgb(0 0 0/.03),0 3px 9px rgb(0 0 0/.04),0 1px 1px rgb(0 0 0/.05);}
.btn svg {pointer-events:none;flex-shrink:0}
.btn:focus-visible, .btn[data-state="focus"] {outline:1px solid var(--focus-ring,var(--color-ring));outline-offset:-1px}
.btn[data-state="disabled"] {pointer-events:none;cursor:not-allowed;opacity:.55}
.btn[data-intent="accent"] {--intent-bg:var(--color-primary);--intent-bg-soft:var(--color-primary-soft);--intent-bg-soft-hover:var(--color-primary-soft-hover);--intent-text:var(--color-primary-ink);--intent-text-on-bg:var(--color-primary-foreground);--intent-text-hover:var(--color-primary-ink);--intent-border:var(--color-border-2);--intent-border-solid:color-mix(in oklch,var(--color-primary) 80%,black);--intent-highlight:oklch(1 0 0/.12);--intent-bg-hover:var(--color-primary-soft);--intent-bg-solid-hover:color-mix(in oklch,var(--color-primary) 92%,black)}
.btn[data-intent="danger"] {--intent-bg:var(--color-destructive);--intent-bg-soft:var(--color-destructive-soft);--intent-bg-soft-hover:var(--color-destructive-soft-hover);--intent-text:var(--color-destructive);--intent-text-on-bg:var(--color-destructive-foreground);--intent-text-hover:var(--color-destructive);--intent-border:var(--color-border-2);--intent-border-solid:color-mix(in oklch,var(--color-destructive) 80%,black);--intent-highlight:oklch(1 0 0/.12);--intent-bg-hover:var(--color-destructive-soft);--intent-bg-solid-hover:color-mix(in oklch,var(--color-destructive) 92%,white)}
.btn[data-variant="solid"] {background:var(--intent-bg,var(--color-button));border-color:var(--intent-border-solid,var(--intent-border,var(--color-border-2)));color:var(--intent-text-on-bg,var(--color-foreground));--focus-ring:var(--intent-text-on-bg,var(--color-ring));box-shadow:inset 0 1px var(--intent-highlight,var(--color-highlight-top)),var(--sh-plate)}
.btn[data-variant="solid"]:hover, .btn[data-variant="solid"][data-state="hover"] {background:var(--intent-bg-solid-hover,var(--color-button-hover))}
.btn[data-variant="solid"]:active, .btn[data-variant="solid"][data-state="active"] {box-shadow:none;filter:brightness(.97)}
.btn[data-variant="soft"] {background:var(--intent-bg-soft,var(--color-secondary));color:var(--intent-text,var(--color-foreground))}
.btn[data-variant="soft"]:hover, .btn[data-variant="soft"][data-state="hover"] {background:var(--intent-bg-soft-hover,var(--color-secondary-hover))}
.btn[data-variant="ghost"], .btn[data-variant="bare"] {background:transparent;color:var(--intent-text,var(--color-muted-foreground-1))}
.btn[data-variant="ghost"]:hover, .btn[data-variant="ghost"][data-state="hover"] {color:var(--intent-text-hover,var(--color-foreground));background:var(--intent-bg-hover,var(--color-secondary))}
.btn[data-variant="ghost"][data-state="selected"] {background:var(--color-secondary);color:var(--color-foreground)}
.btn[data-variant="bare"]:hover, .btn[data-variant="bare"][data-state="hover"], .btn[data-variant="bare"][data-state="selected"] {color:var(--intent-text-hover,var(--color-foreground))}
.btn[data-variant="outline"] {background:transparent;border-color:var(--intent-border,var(--color-border-2));color:var(--intent-text,var(--color-foreground))}
.btn[data-variant="outline"]:hover, .btn[data-variant="outline"][data-state="hover"] {background:var(--intent-bg-hover,var(--color-secondary))}
.btn[data-variant="link"] {background:transparent;color:var(--intent-text,var(--color-text-link));text-underline-offset:2px}
.btn[data-variant="link"]:hover, .btn[data-variant="link"][data-state="hover"] {text-decoration:underline}
.btn[data-variant="link"][data-state="disabled"], .btn[data-variant="bare"][data-state="disabled"] {opacity:.4}
.btn[data-variant="inverse"] {background:var(--intent-bg,var(--color-inverse));color:var(--intent-text-on-bg,var(--color-inverse-text))}
.btn[data-variant="inverse"]:hover, .btn[data-variant="inverse"][data-state="hover"] {background:var(--intent-bg-solid-hover,var(--color-inverse-hover))}
.btn[data-variant="inverse"][data-state="disabled"] {opacity:.5}
.btn[data-variant="segmented"] {background:transparent;color:var(--intent-text,var(--color-segmented-foreground))}
.btn[data-variant="segmented"]:hover, .btn[data-variant="segmented"][data-state="hover"] {color:var(--intent-text-hover,var(--color-foreground))}
.btn[data-variant="segmented"][data-state="selected"] {background:var(--intent-bg,var(--color-card));color:var(--intent-text-hover,var(--color-foreground));box-shadow:var(--sh-card)}
.btn:not([data-variant="solid"]):not([data-variant="inverse"]):active, .btn:not([data-variant="solid"]):not([data-variant="inverse"])[data-state="active"] {filter:brightness(.97)}
.btn[data-variant="inverse"]:active, .btn[data-variant="inverse"][data-state="active"] {filter:brightness(.95)}
.btn[data-size="xs"] {height:var(--spacing-control-xs);padding:0 8px;font-size:var(--text-xs);gap:6px}
.btn[data-size="sm"] {height:var(--spacing-control-sm);padding:0 8px;font-size:var(--text-xs);gap:6px}
.btn[data-size="base"] {height:var(--spacing-control-base);padding:0 10px;font-size:var(--text-sm);gap:8px}
.btn[data-size="lg"] {height:var(--spacing-control-lg);padding:0 16px;font-size:var(--text-sm);gap:8px}
.btn[data-size="xs"] svg {width:var(--spacing-icon-xs);height:var(--spacing-icon-xs)}
.btn[data-size="sm"] svg {width:var(--spacing-icon-sm);height:var(--spacing-icon-sm)}
.btn[data-size="base"] svg, .btn[data-size="lg"] svg {width:var(--spacing-icon-base);height:var(--spacing-icon-base)}
.btn[data-size="xs"] svg:first-child, .btn[data-size="sm"] svg:first-child, .btn[data-size="base"] svg:first-child, .btn[data-size="lg"] svg:first-child {margin-left:-2px}
.btn[data-size="xs"] svg:last-child, .btn[data-size="sm"] svg:last-child, .btn[data-size="base"] svg:last-child, .btn[data-size="lg"] svg:last-child {margin-right:-2px}
.btn[data-size^="icon"] .lbl {display:none}
.btn[data-size="icon-xs"] {width:var(--spacing-control-xs);height:var(--spacing-control-xs);padding:0}
.btn[data-size="icon-sm"] {width:var(--spacing-control-sm);height:var(--spacing-control-sm);padding:0}
.btn[data-size="icon-base"] {width:var(--spacing-control-base);height:var(--spacing-control-base);padding:0}
.btn[data-size="icon-xs"] svg {width:var(--spacing-icon-xs);height:var(--spacing-icon-xs)}
.btn[data-size="icon-sm"] svg {width:var(--spacing-icon-sm);height:var(--spacing-icon-sm)}
.btn[data-size="icon-base"] svg {width:var(--spacing-icon-base);height:var(--spacing-icon-base)}
.btn[data-shape="segment-start"] {border-top-right-radius:0;border-bottom-right-radius:0;border-right-width:0;box-shadow:none}
.btn[data-shape="segment-end"] {border-top-left-radius:0;border-bottom-left-radius:0;box-shadow:none}
.btn .i0, .btn .i1 {display:contents}
